'use strict';
/* ===== [LEADER] Trang tóm tắt lãnh đạo dùng chung — route /api/leader-dashboard (alias /api/leader).
 * Tổng hợp số liệu 2 nguồn Supabase (Facebook + Email) cho 1 khoảng ngày, hiển thị dạng in-1-trang.
 * File tự chứa (fetch riêng, không phụ thuộc fb-dashboard.js/email-dashboard.js) — đúng quy ước repo. ===== */
const https = require('https');
const LOGO_URI = 'data:image/png;base64,';
const REACH_TARGET = 70;

/* ── fetch Facebook (SUPABASE_URL / SUPABASE_SERVICE_KEY) ── */
const dbClient = require('../lib/db-client');
const FONT_FACE = require('../lib/fonts');
function fbGet(path){
  if(dbClient.isEnabled())return dbClient.get(path).then(function(d){return Array.isArray(d)?d:[];}).catch(function(){return [];});
  return new Promise(function(resolve){
    var base=(process.env.SUPABASE_URL||'').replace(/\/$/,''),key=process.env.SUPABASE_SERVICE_KEY||'';
    if(!base||!key)return resolve([]);
    https.get(base+path,{headers:{apikey:key,Authorization:'Bearer '+key,Accept:'application/json'}},function(r){
      var b='';r.on('data',function(c){b+=c;});r.on('end',function(){try{var d=JSON.parse(b);resolve(Array.isArray(d)?d:[]);}catch(e){resolve([]);}});
    }).on('error',function(){resolve([]);});
  });
}
// Khi thiếu SUPABASE_URL/SUPABASE_SERVICE_KEY, fb-dashboard.js tự sinh dữ liệu mock để demo —
// làm tương tự ở đây để Top 5 bài Facebook / KPI Facebook trên trang lãnh đạo khớp với dashboard chính.
function genMockPosts(){
  var seed=20260622;function rnd(){seed=(seed*1103515245+12345)&0x7fffffff;return seed/0x7fffffff;}
  function ri(a,b){return Math.floor(a+rnd()*(b-a+1));}
  var types=['Ảnh','Video','Reel','Text','Link'];
  var topics=['Sản phẩm vay','Tuyển dụng','Sự kiện','Thông báo','CSR','Khuyến mãi'];
  var samples=['Ra mắt gói vay ưu đãi','Hướng dẫn mở tài khoản online','60 giây hiểu về lãi kép',
    'Thông báo lịch nghỉ lễ','Album tri ân khách hàng','Cơ hội nghề nghiệp tại SHB',
    'Chương trình hoàn tiền thẻ tín dụng','Cẩm nang tài chính cá nhân','SHB đồng hành cùng cộng đồng',
    'Mở thẻ nhận quà liền tay','Lãi suất tiết kiệm mới','Sự kiện kết nối doanh nghiệp'];
  var now=Date.now(),DAY=864e5,posts=[];
  for(var i=0;i<38;i++){
    var type=types[ri(0,4)],ageD=Math.floor(rnd()*90),ts=now-ageD*DAY-ri(0,86399)*1000;
    var views=ri(8000,60000),base=views/1000;
    var like=ri(Math.round(base*30),Math.round(base*70)),love=ri(Math.round(base*8),Math.round(base*40));
    var haha=ri(0,Math.round(base*12)),wow=ri(0,Math.round(base*10));
    var sad=ri(0,Math.round(base*4)),angry=ri(0,Math.round(base*3));
    var comments=ri(Math.round(base*2),Math.round(base*12)),shares=ri(Math.round(base),Math.round(base*10));
    posts.push({
      post_id:'p'+i, created_time:new Date(ts).toISOString(), views:views,
      like_count:like, love_count:love, haha_count:haha, wow_count:wow, sad_count:sad, angry_count:angry,
      comments:comments, shares:shares,
      message:samples[ri(0,samples.length-1)]+(rnd()>.5?' #'+topics[ri(0,5)]:''),
      topic:topics[ri(0,5)],
    });
  }
  return posts;
}
// fb-dashboard.js gộp bài Trang (fb_posts) VÀ bài Group "SHB Một Nhà" (fb_group_posts, nạp qua
// userscript -> /api/ingest) làm 1 nguồn nội dung — làm tương tự ở đây để không bỏ sót phần lớn
// bài viết thực tế (chủ yếu nằm ở group, không phải page).
function fetchFbPosts(){
  if(!process.env.SUPABASE_URL||!process.env.SUPABASE_SERVICE_KEY)return Promise.resolve(genMockPosts());
  return Promise.all([
    fbGet('/rest/v1/fb_posts?select=post_id,created_time,views,like_count,love_count,haha_count,wow_count,sad_count,angry_count,comments,shares,message,topic&order=created_time.desc&limit=800'),
    fbGet('/rest/v1/fb_group_posts?select=post_id,created_time,reach,engagement,comments,title&order=created_time.desc&limit=500'),
  ]).then(function(r){
    var pagePosts=r[0]||[];
    var groupPosts=(r[1]||[]).map(function(g){
      var eng=g.engagement||0,cmt=g.comments||0;
      return {
        post_id:'g_'+g.post_id, created_time:g.created_time, views:g.reach||0,
        like_count:Math.max(0,eng-cmt), love_count:0, haha_count:0, wow_count:0, sad_count:0, angry_count:0,
        comments:cmt, shares:0, message:g.title||'(không có nội dung)', topic:'',
      };
    });
    return pagePosts.concat(groupPosts);
  });
}

/* ── fetch Email (EMAIL_SUPABASE_URL / EMAIL_SUPABASE_SERVICE_KEY) ── */
const EMAIL_SUPABASE_URL = process.env.EMAIL_SUPABASE_URL || process.env.SUPABASE_URL || '';
const EMAIL_SERVICE_KEY  = process.env.EMAIL_SUPABASE_SERVICE_KEY || process.env.SUPABASE_SERVICE_KEY || '';
function fetchEmailLogs(){
  // Có MySQL nội bộ (MYSQL_HOST) thì fetchOne bên dưới tự rẽ sang db-client — chỉ chặn khi thiếu cả 2.
  if(!dbClient.isEnabled()&&(!EMAIL_SUPABASE_URL||!EMAIL_SERVICE_KEY))return Promise.resolve([]);
  var host=EMAIL_SUPABASE_URL.replace(/^https?:\/\//,'');
  var sel='pos,rcpt,msg_type,initiative,campaign,timestamp:ts';
  var hdrs={apikey:EMAIL_SERVICE_KEY,Authorization:'Bearer '+EMAIL_SERVICE_KEY,Accept:'application/json'};
  var PAGE=1000;
  var base='/rest/v1/events?select='+encodeURIComponent(sel);
  function fetchOne(path){
    if(dbClient.isEnabled())return dbClient.get(path).catch(function(){return [];});
    return new Promise(function(resolve){
      var done=false;function fin(v){if(!done){done=true;resolve(v);}}
      var req=https.request({hostname:host,path:path,headers:hdrs},function(r){
        var buf='';r.on('data',function(c){buf+=c;});r.on('end',function(){try{var d=JSON.parse(buf);fin(Array.isArray(d)?d:[]);}catch(e){fin([]);}});r.on('error',function(){fin([]);});
      });
      req.setTimeout(7000,function(){req.destroy();fin([]);});
      req.on('error',function(){fin([]);});
      req.end();
    });
  }
  function fetchParallel(basePath,pages){
    var reqs=[];for(var i=0;i<pages;i++)reqs.push(fetchOne(basePath+'&limit='+PAGE+'&offset='+(i*PAGE)));
    return Promise.all(reqs).then(function(results){return [].concat.apply([],results);});
  }
  return Promise.all([
    fetchParallel(base+'&pos=eq.sent&order=ts.asc',5),
    fetchParallel(base+'&pos=neq.sent&order=ts.desc',2)
  ]).then(function(r){return r[0].concat(r[1]);}).catch(function(){return [];});
}

/* ── helpers dùng chung (copy từ fb/email-dashboard.js để giữ đúng logic) ── */
function nf(n){return (Math.round(n)||0).toLocaleString('vi-VN');}
function pc(n){return (Math.round(n*10)/10);}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function norm(s){return String(s==null?'':s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d');}
function fmtCamp(c){return (c||'').replace(/-/g,' ').replace(/\b\w/g,function(x){return x.toUpperCase();});}
var PROJECTS=[
  ['SAHA Next Gen',['saha next gen','next gen','nextgen']],['SAHA Branch',['saha branch']],['SHB SAHA App',['saha app']],
  ['SSP',['ssp']],['KPI',['kpi']],['ALM',['alm']],['EGP',['egp']],
  ['Edoc',['edoc','e-doc']],['Website',['website']],['Reward',['reward']],
  ['Sinh lời Tự động',['sinh loi tu dong','sinh loi']],
  ['CCS/CDS',['ccs','cds']],
  ['SHB Future Lead',['future lead','futurelead']],
  ['SHB Transformation Talk',['transformation talk','transformation']],
  ['Sunline',['sunline']],
  ['Chuyển tiền quốc tế',['chuyen tien quoc te','ctqt']]
];
function projectOf(msg,topic){var t=norm((msg||'')+' '+(topic||''));for(var i=0;i<PROJECTS.length;i++){var ks=PROJECTS[i][1];for(var j=0;j<ks.length;j++){if(t.indexOf(ks[j])>-1)return PROJECTS[i][0];}}return 'Khác';}
function deltaTxt(cur,prev,goodUp){
  if(prev==null||prev===0){if(cur>0)return {cls:'up',txt:'mới'};return null;}
  var p=Math.round((cur-prev)/prev*100);if(p===0)return {cls:'flat',txt:'±0'};
  var up=p>0,cls=(up===goodUp)?'up':'down';
  return {cls:cls,txt:(up?'▲ ':'▼ ')+Math.abs(p)+'%'};
}
function chip(d){if(!d)return '';return '<span class="delta '+d.cls+'">'+d.txt+'</span>';}

/* ── tổng hợp Facebook theo khoảng ngày ── */
function fbAgg(posts,days){
  var now=Date.now(),cutNow=days>0?now-days*864e5:0,cutPrev=days>0?cutNow-days*864e5:0;
  function win(lo,hi){
    var views=0,eng=0,n=0;
    posts.forEach(function(p){var t=+new Date(p.created_time);if(!(t>lo&&t<=hi))return;n++;views+=p.views||0;
      eng+=(p.like_count||0)+(p.love_count||0)+(p.haha_count||0)+(p.wow_count||0)+(p.sad_count||0)+(p.angry_count||0)+(p.comments||0)+(p.shares||0);});
    return {views:views,eng:eng,n:n,er:views>0?pc(eng/views*100):0};
  }
  return {cur:win(cutNow,now),prev:win(cutPrev,cutNow)};
}

/* ── tổng hợp Email theo khoảng ngày (person-level, khớp logic hasSent/opened của email-dashboard.js) ── */
// Loại campaign test/dev (VD "Test Gitlab", "Test Vba412" gửi lúc chạy thử pipeline/VBA)
// khỏi TẤT CẢ tổng hợp trên trang lãnh đạo — số liệu test lẫn vào KPI/Top 5 khiến
// "Email · Reach" bị đội lên tới >100% (đúng cảnh báo đã ghi trong email-dashboard.js:
// "Open Rate > 100% = dữ liệu test hoặc thiếu sent events") và Top 5 toàn campaign giả.
function isTestCampaign(name){return /^test\b/i.test(String(name||'').trim());}
function emailAgg(logs,days){
  var now=Date.now(),cutNow=days>0?now-days*864e5:0,cutPrev=days>0?cutNow-days*864e5:0;
  function win(lo,hi){
    var sent={},opened={},clicked={},manSent={},manOpened={};
    logs.forEach(function(l){var t=+new Date(l.timestamp);if(!(t>lo&&t<=hi)||isTestCampaign(l.campaign))return;
      if(l.pos==='sent'){sent[l.rcpt]=1;if(l.msg_type==='mandatory')manSent[l.rcpt]=1;}
      if(l.pos==='top'){opened[l.rcpt]=1;if(l.msg_type==='mandatory')manOpened[l.rcpt]=1;}
      if(l.pos==='click')clicked[l.rcpt]=1;
    });
    var sN=Object.keys(sent).length,oN=Object.keys(opened).length,cN=Object.keys(clicked).length,mS=Object.keys(manSent).length,mO=Object.keys(manOpened).length;
    return {sent:sN,opened:oN,clicked:cN,reach:sN>0?Math.round(oN/sN*100):null,ctor:oN>0?Math.round(cN/oN*100):null,manSent:mS,manOpened:mO,manRate:mS>0?Math.round(mO/mS*100):null,manRemain:Math.max(0,mS-mO)};
  }
  return {cur:win(cutNow,now),prev:win(cutPrev,cutNow)};
}

/* ── chéo Squad/Dự án — khớp theo tên chuẩn hoá giữa projectOf(FB) và initiative(Email) ── */
function crossover(posts,logs,days){
  var now=Date.now(),cutNow=days>0?now-days*864e5:0;
  var fbMap={};
  posts.forEach(function(p){var t=+new Date(p.created_time);if(!(t>cutNow&&t<=now))return;var proj=projectOf(p.message,p.topic);if(proj==='Khác')return;
    var k=norm(proj);if(!fbMap[k])fbMap[k]={name:proj,views:0,eng:0,n:0};
    fbMap[k].views+=p.views||0;fbMap[k].eng+=(p.like_count||0)+(p.love_count||0)+(p.haha_count||0)+(p.wow_count||0)+(p.sad_count||0)+(p.angry_count||0)+(p.comments||0)+(p.shares||0);fbMap[k].n++;});
  var emMap={};
  logs.forEach(function(l){var t=+new Date(l.timestamp);if(!(t>cutNow&&t<=now))return;if(!l.initiative)return;
    var k=norm(l.initiative);if(!emMap[k])emMap[k]={name:l.initiative,sent:{},opened:{}};
    if(l.pos==='sent')emMap[k].sent[l.rcpt]=1;if(l.pos==='top')emMap[k].opened[l.rcpt]=1;});
  var rows=[];
  Object.keys(fbMap).forEach(function(k){
    if(!emMap[k])return;
    var e=emMap[k],f=fbMap[k],sN=Object.keys(e.sent).length,oN=Object.keys(e.opened).length;
    rows.push({name:f.name,emailReach:sN>0?Math.round(oN/sN*100):null,emailSent:sN,fbViews:f.views,fbER:f.views>0?pc(f.eng/f.views*100):0,fbPosts:f.n});
  });
  rows.sort(function(a,b){return b.fbViews-a.fbViews;});
  return rows;
}

/* ── Top 5 bài Facebook theo tương tác trong kỳ ── */
function topFbPosts(posts,days){
  var now=Date.now(),cut=days>0?now-days*864e5:0;
  return posts.filter(function(p){var t=+new Date(p.created_time);return t>cut&&t<=now;})
    .map(function(p){var eng=(p.like_count||0)+(p.love_count||0)+(p.haha_count||0)+(p.wow_count||0)+(p.sad_count||0)+(p.angry_count||0)+(p.comments||0)+(p.shares||0);
      return {msg:p.message||'(không có nội dung)',views:p.views||0,eng:eng,er:p.views>0?pc(eng/p.views*100):0};})
    .sort(function(a,b){return b.eng-a.eng;}).slice(0,5);
}
/* ── Top 5 chiến dịch Email theo tỉ lệ mở trong kỳ ── */
function topEmailCampaigns(logs,days){
  var now=Date.now(),cut=days>0?now-days*864e5:0;
  var map={};
  logs.forEach(function(l){var t=+new Date(l.timestamp);if(!(t>cut&&t<=now)||!l.campaign||isTestCampaign(l.campaign))return;
    var k=l.campaign;if(!map[k])map[k]={name:k,sent:{},opened:{}};
    if(l.pos==='sent')map[k].sent[l.rcpt]=1;if(l.pos==='top')map[k].opened[l.rcpt]=1;});
  return Object.keys(map).map(function(k){var c=map[k],sN=Object.keys(c.sent).length,oN=Object.keys(c.opened).length;
    return {name:c.name,sent:sN,opened:oN,reach:sN>0?Math.round(oN/sN*100):null};})
    .filter(function(c){return c.sent>0;}).sort(function(a,b){return (b.reach||0)-(a.reach||0);}).slice(0,5);
}
function buildInsights(fb,email){
  var ins=[];
  if(email.cur.reach!=null){
    if(email.cur.reach<REACH_TARGET)ins.push({t:'warn',x:'Email reach kỳ này <b>'+email.cur.reach+'%</b> — dưới mục tiêu '+REACH_TARGET+'%.'});
    else ins.push({t:'good',x:'Email reach <b>'+email.cur.reach+'%</b> — đạt mục tiêu '+REACH_TARGET+'%.'});
  }
  if(email.cur.manSent>0&&email.cur.manRemain>0)ins.push({t:'warn',x:'Còn <b>'+email.cur.manRemain+'</b> người chưa xác nhận email bắt buộc trong kỳ.'});
  var fbD=deltaTxt(fb.cur.views,fb.prev.views,true);
  if(fbD)ins.push({t:fbD.cls==='up'?'good':'warn',x:'Facebook lượt xem '+(fbD.cls==='up'?'tăng':'giảm')+' <b>'+fbD.txt.replace('▲ ','').replace('▼ ','')+'</b> so kỳ trước.'});
  if(!ins.length)ins.push({t:'info',x:'Chưa đủ dữ liệu để đưa ra nhận định trong kỳ này.'});
  return ins;
}

